def enrich(info, base_faq):
    for slug, (katha, vishesh, q) in EKA_MORE.items():
        d = info.get(slug)
        if not d: continue
        d["mahatva"] = [d["mahatva"][0], katha, vishesh] + d["mahatva"][1:]
        d["faq"] = [q] + list(base_faq)
